import{_ as e,o as n,c as s,a0 as i}from"./chunks/framework.BYCjvD8D.js";const d=JSON.parse('{"title":"Live MarI/O-style visualisation","description":"","frontmatter":{},"headers":[],"relativePath":"live-visualisation.md","filePath":"live-visualisation.md"}'),t={name:"live-visualisation.md"};function r(o,a,l,p,c,h){return n(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="live-mari-o-style-visualisation" tabindex="-1">Live MarI/O-style visualisation <a class="header-anchor" href="#live-mari-o-style-visualisation" aria-label="Permalink to &quot;Live MarI/O-style visualisation&quot;">​</a></h1><p>The <a href="https://www.youtube.com/watch?v=qv6UVOQ0F44" target="_blank" rel="noreferrer">2015 MarI/O demonstration</a> is the visual reference for a live left-to-right decision pipeline. Our implementation keeps the same <strong>conceptual visual grammar</strong>, with original artwork and a clean-room TypeScript algorithm.</p><h2 id="live-pipeline" tabindex="-1">Live pipeline <a class="header-anchor" href="#live-pipeline" aria-label="Permalink to &quot;Live pipeline&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ACTUAL PRE-ACTION GAME STATE</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  observePlatform()</span></span>
<span class="line"><span>  13 × 13 terrain + enemy sensors</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── landscape / enemy SVG (169 cells)</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  traceGenome()  ← same feed-forward function as training</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── SVG sensory nodes (169)</span></span>
<span class="line"><span>        ├── actual enabled gene connections</span></span>
<span class="line"><span>        ├── positive weights in green / negative in pink</span></span>
<span class="line"><span>        ├── live hidden neuron activations</span></span>
<span class="line"><span>        └── output neuron values</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  LEFT / RIGHT / JUMP</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├── actual action recorded in ReplayPoint.action</span></span>
<span class="line"><span>        ├── controller SVG button illumination</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  stepPlatform()</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  post-action position displayed in the game</span></span></code></pre></div><h2 id="frame-synchronisation" tabindex="-1">Frame synchronisation <a class="header-anchor" href="#frame-synchronisation" aria-label="Permalink to &quot;Frame synchronisation&quot;">​</a></h2><p>The browser game replays exactly the same recorded episode as the visualization. For replay frame <strong>n</strong>, the landscape and neural activations are computed from the state <strong>before</strong> that action (frame n−1, or the initial reset state for n=0). Buttons are taken from the action actually executed on frame n, <strong>not estimated from movement</strong>.</p><p>The live circuit refreshes with the replay clock. The screen simulation and controller remain synchronised when replay is paused. A deterministic test explicitly verifies both the initial and second-frame policy correspondence.</p><h2 id="javascript-typescript-mario-style-games-investigated" tabindex="-1">JavaScript / TypeScript Mario-style games investigated <a class="header-anchor" href="#javascript-typescript-mario-style-games-investigated" aria-label="Permalink to &quot;JavaScript / TypeScript Mario-style games investigated&quot;">​</a></h2><ul><li><strong><a href="https://github.com/fkucukkara/mario" target="_blank" rel="noreferrer">Super Mario TS (fkucukkara/mario)</a></strong> — TypeScript, Phaser 3, Vite, MIT-licensed code and procedurally generated placeholder graphics; suitable as a <em>future alternative gameplay backend</em>.</li><li><strong><a href="https://github.com/aayushsharma-io/mariojs" target="_blank" rel="noreferrer">MarioJS (aayushsharma-io/mariojs)</a></strong> — vanilla JavaScript with an MIT licence, but its art and gameplay may involve Nintendo intellectual property.</li><li><strong><a href="https://github.com/carlomigueldy/sprout-runner" target="_blank" rel="noreferrer">Sprout Runner (carlomigueldy/sprout-runner)</a></strong> — original browser platformer with no external game assets, suitable for studying general platforming mechanics.</li><li><strong><a href="https://github.com/ifthenelse/Super-Mario-Bros-AI" target="_blank" rel="noreferrer">ifthenelse/Super-Mario-Bros-AI</a></strong> — Python/stable-retro/neat-python, <em>not</em> a browser implementation.</li></ul><p>The current production demo continues to use the <strong>existing original TypeScript platform simulator</strong> because a single shared game state is essential for honest training telemetry. A Phaser environment adapter is a later milestone: merely rendering an unrelated game while training on our original physics would create misleading visualisation.</p><h2 id="graphics-processor-note" tabindex="-1">Graphics processor note <a class="header-anchor" href="#graphics-processor-note" aria-label="Permalink to &quot;Graphics processor note&quot;">​</a></h2><p>The three-panel neural-network visualisation is <strong>SVG</strong>. The side game is <strong>Canvas 2D</strong>, and the optional lower topology visualisation remains <strong>WebGPU/WebGL via Three.js</strong>. Training remains a <strong>CPU Web Worker</strong> task. Do not conflate WebGPU rendering with GPU-powered neuroevolution.</p><h2 id="provenance-and-scope" tabindex="-1">Provenance and scope <a class="header-anchor" href="#provenance-and-scope" aria-label="Permalink to &quot;Provenance and scope&quot;">​</a></h2><p>No Nintendo ROMs, sprites or soundtrack, and no redistribution of SethBling&#39;s Lua program. This is a new educational implementation of graph topology evolution and real-time observation/action explanations.</p>`,14)])])}const m=e(t,[["render",r]]);export{d as __pageData,m as default};
